import{_ as o,o as a,c as t,a2 as i}from"./chunks/framework.Bg-Zxr5O.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/ONEWAY.md","filePath":"manual-en/ONEWAY.md","lastUpdated":1785684581000}'),n={name:"manual-en/ONEWAY.md"};function s(d,e,c,l,r,f){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h3 id="_15-14-oneway" tabindex="-1">15.14 ONEWAY <a class="header-anchor" href="#_15-14-oneway" aria-label="Permalink to &quot;15.14 ONEWAY&quot;">​</a></h3><pre><code>ONEWAY
        [/VARIABLES = ] var_list BY var
        /MISSING={ANALYSIS,LISTWISE} {EXCLUDE,INCLUDE}
        /CONTRAST= value1 [, value2] ... [,valueN]
        /STATISTICS={DESCRIPTIVES,HOMOGENEITY}
        /POSTHOC={BONFERRONI, GH, LSD, SCHEFFE, SIDAK, TUKEY, ALPHA ([value])}
</code></pre><p>The <code>ONEWAY</code> procedure performs a one-way analysis of variance of variables factored by a single independent variable. It is used to compare the means of a population divided into more than two groups.</p><p>The dependent variables to be analysed should be given in the <code>VARIABLES</code> subcommand. The list of variables must be followed by the <code>BY</code> keyword and the name of the independent (or factor) variable.</p><p>You can use the <code>STATISTICS</code> subcommand to tell PSPP to display ancillary information. The options accepted are:</p><ul><li>DESCRIPTIVES Displays descriptive statistics about the groups factored by the independent variable.</li><li>HOMOGENEITY Displays the Levene test of Homogeneity of Variance for the variables and their groups.</li></ul><p>The <code>CONTRAST</code> subcommand is used when you anticipate certain differences between the groups. The subcommand must be followed by a list of numerals which are the coefficients of the groups to be tested. The number of coefficients must correspond to the number of distinct groups (or values of the independent variable). If the total sum of the coefficients are not zero, then PSPP will display a warning, but will proceed with the analysis. The <code>CONTRAST</code> subcommand may be given up to 10 times in order to specify different contrast tests. The <code>MISSING</code> subcommand defines how missing values are handled. If <code>LISTWISE</code> is specified then cases which have missing values for the independent variable or any dependent variable are ignored. If <code>ANALYSIS</code> is specified, then cases are ignored if the independent variable is missing or if the dependent variable currently being analysed is missing. The default is <code>ANALYSIS</code>. A setting of <code>EXCLUDE</code> means that variables whose values are user-missing are to be excluded from the analysis. A setting of <code>INCLUDE</code> means they are to be included. The default is <code>EXCLUDE</code>.</p><p>Using the <code>POSTHOC</code> subcommand you can perform multiple pairwise comparisons on the data. The following comparison methods are available:</p><ul><li><code>LSD</code> Least Significant Difference.</li><li><code>TUKEY</code> Tukey Honestly Significant Difference.</li><li><code>BONFERRONI</code> Bonferroni test.</li><li><code>SCHEFFE</code> Scheffé’s test.</li><li><code>SIDAK</code> Sidak test.</li><li><code>GH</code> The Games-Howell test.</li></ul><p>Use the optional syntax <code>ALPHA(value)</code> to indicate that <code>ONEWAY</code> should perform the posthoc tests at a confidence level of value. If <code>ALPHA(value)</code> is not specified, then the confidence level used is 0.05.</p>`,10)])])}const u=o(n,[["render",s]]);export{p as __pageData,u as default};
